import{_ as e,o,c,a5 as a}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"watch相关","description":"当然，让我们从基础开始介绍一下 Vue 3 中的 watchEffect 和 watch API。 watchEffect watchEffect 是一个用于追踪响应式依赖的函数，当这些依赖改变时，它会重新执行。它类似于 Vue 2 中的 watch，但是它自动追踪所有被引用的响。","frontmatter":{"title":"watch相关","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"当然，让我们从基础开始介绍一下 Vue 3 中的 watchEffect 和 watch API。 watchEffect watchEffect 是一个用于追踪响应式依赖的函数，当这些依赖改变时，它会重新执行。它类似于 Vue 2 中的 watch，但是它自动追踪所有被引用的响。","sidebarWeight":118,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vue3/组合式api/watch相关.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/组合式api/watch相关.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/组合式api/watch相关.md"}'),n={name:"posts/Vue系统教程/03-响应式与组合式 API/组合式api/watch相关.md"};function l(p,t,u,s,r,f){return o(),c("div",null,[...t[0]||(t[0]=[a('<div><h1 id="watch相关" tabindex="-1">watch相关 <a class="header-anchor" href="#watch相关" aria-label="Permalink to &quot;watch相关&quot;">​</a></h1><blockquote><p>本节目标：理解“watch相关”的核心思路，并能把它用于实际开发或面试表达。 当然，让我们从基础开始介绍一下 Vue 3 中的 watchEffect 和 watch API。 <strong>watchEffect</strong> watchEffect 是一个用于追踪响应式依赖的函数，当这些依赖改变时，它会重新执行。它类似于 Vue 2 中的 watch，但是它自动追踪所有被引用的响应式依赖，你无需明确声明它们。</p></blockquote><p><strong>基础用法</strong> 下面是一个基本的示例： import { ref, watchEffect } from &#39;vue&#39; const count = ref(0); watchEffect(() =&gt; console.log(count.value)) // -&gt; 输出 0 count.value++ // -&gt; 输出 1 在这个示例中，watchEffect 函数接收一个函数作为参数（我们叫它&quot;副作用函数&quot;）。在副作用函数中，我们记录 count.value。因为 count 是一个响应式的引用，当 count.value 值改变时，watchEffect 就会重新执行副作用函数。</p><p><strong>停止 watchEffect</strong> watchEffect 返回一个停止函数，当你不再需要监听时，可以调用这个函数来停止监听： const stop = watchEffect(() =&gt; console.log(count.value)) // 当你不再需要监听时 stop()</p><p>停止监听的场景 在某些情况下，你可能需要停止监听数据的改变。这通常发生在以下情况：</p><ul><li>你在组件卸载（例如用户离开了一个页面或关闭了一个模态）时，想要停止监听数据，防止在组件不再存在时尝试更新它的状态，这可能会导致错误或内存泄露。</li><li>你的监听回调有一些昂贵的操作（例如，API 请求或复杂的计算），你只在特定条件下需要这些操作。一旦条件不再满足，你就可以停止监听。</li><li>你的监听回调执行某个一次性操作（例如，获取用户的初始位置）。获取到数据之后，你就可以停止监听。</li></ul><p><strong>watch</strong> // 侦听单个来源 function watch&lt;T&gt;( source: WatchSource&lt;T&gt;, callback: WatchCallback&lt;T&gt;, options?: WatchOptions ): StopHandle</p><p>// 侦听多个来源 function watch&lt;T&gt;( sources: WatchSource&lt;T&gt;[], callback: WatchCallback&lt;T[]&gt;, options?: WatchOptions ): StopHandle</p><p>type WatchCallback&lt;T&gt; = ( value: T, oldValue: T, onCleanup: (cleanupFn: () =&gt; void) =&gt; void ) =&gt; void</p><p>type WatchSource&lt;T&gt; = | Ref&lt;T&gt; // ref | (() =&gt; T) // getter | T extends object ? T : never // 响应式对象 interface WatchOptions extends WatchEffectOptions { immediate?: boolean // 默认：false deep?: boolean // 默认：false flush?: &#39;pre&#39; | &#39;post&#39; | &#39;sync&#39; // 默认：&#39;pre&#39; onTrack?: (event: DebuggerEvent) =&gt; void onTrigger?: (event: DebuggerEvent) =&gt; void }</p><p>watch 是 watchEffect 的一个更自定义的版本。它允许你：</p><ul><li>明确地声明需要监听的响应式依赖</li><li>访问先前的值和当前的值</li><li>控制监听器何时运行</li></ul><p><strong>基础用法</strong> 下面是一个基本的示例： import { ref, watch } from &#39;vue&#39; const count = ref(0) watch(count, (newValue, oldValue) =&gt; { console.log(<code>count changed from ${oldValue} to ${newValue}</code>) }) 在这个示例中，watch 函数接收两个参数：被监听的源和一个回调函数。当 count.value 改变时，回调函数会被调用，并接收新值和旧值作为参数。</p><p>选项：immediate 和 deep watch 函数的第三个参数是一个选项对象。这个对象有两个主要的选项：</p><ul><li>immediate：如果设为 true，则回调函数会在 watch 启动时立即执行（而不是等到监听的源改变时才执行）。</li><li>deep：如果设为 true，则 watch 将深度跟踪监听的源（当源是一个对象或数组时）。也就是说，如果源是一个对象或数组，当其内部的任何属性改变时，都会触发回调函数。</li></ul><p>watch(count, (newValue, oldValue) =&gt; { console.log(<code>count changed from ${oldValue} to ${newValue}</code>) }, { immediate: true, deep: true })</p><p><strong>停止 watch</strong> 就像 watchEffect，watch 也返回一个停止函数。当你不再需要监听时，可以调用这个函数来停止监听： const stop = watch(count, (newValue, oldValue) =&gt; { console.log(<code>count changed from ${oldValue} to ${newValue}</code>) }) // 当你不再需要监听时 stop()</p><p><strong>监听多个源</strong> 你也可以监听多个源。在这种情况下，你需要将源放在一个数组中，并在回调函数中接收两个数组参数，分别对应新值和旧值： import { ref, watch } from &#39;vue&#39; const count = ref(0) const anotherCount = ref(0) watch([count, anotherCount], ([newCount, newAnotherCount], [oldCount, oldAnotherCount]) =&gt; { console.log(<code>count changed from ${oldCount} to ${newCount}</code>) console.log(<code>anotherCount changed from ${oldAnotherCount} to ${newAnotherCount}</code>) })</p><p><strong>异步和清理</strong> 如果你在回调函数中执行异步操作，你可能需要在源改变和回调函数重新执行之前取消前一个异步操作。这可以通过在回调函数中接收一个 onCleanup 函数并调用它来实现： import { ref, watch } from &#39;vue&#39; const id = ref(0) const data = ref(null) watch(id, async (newId, oldId, onCleanup) =&gt; { const { response, cancel } = doAsyncWork(newId) // 当 <code>id</code> 改变时，<code>cancel</code> 将被调用，取消前一个未完成的请求 onCleanup(cancel) data.value = await response }) 在这个示例中，每次 id 改变，我们都开始一个新的异步工作（可能是一个 API 调用）。如果 id 在异步工作完成之前又改变了，我们会取消前一个异步工作，这样就不会有未完成的请求了。在异步工作完成后，我们将结果赋给 data.value。</p><p>这些都是关于 watch 和 watchEffect 的基础知识，这两个 API 都是 Vue 3 中用于监听响应式数据的强大工具。通过这两个 API，你可以轻松地跟踪和响应数据的变化。</p><p><strong>watchEffect</strong> 立即运行一个函数，同时响应式地追踪其依赖，并在依赖更改时重新执行。</p><p>function watchEffect( effect: (onCleanup: OnCleanup) =&gt; void, options?: WatchEffectOptions ): StopHandle type OnCleanup = (cleanupFn: () =&gt; void) =&gt; void interface WatchEffectOptions { flush?: &#39;pre&#39; | &#39;post&#39; | &#39;sync&#39; // 默认：&#39;pre&#39; onTrack?: (event: DebuggerEvent) =&gt; void onTrigger?: (event: DebuggerEvent) =&gt; void } type StopHandle = () =&gt; void</p><p>详细信息 第一个参数就是要运行的副作用函数。这个副作用函数的参数也是一个函数，用来注册清理回调。清理回调会在该副作用下一次执行前被调用，可以用来清理无效的副作用，例如等待中的异步请求 (参见下面的示例)。</p><p>第二个参数是一个可选的选项，可以用来调整副作用的刷新时机或调试副作用的依赖。</p><p>默认情况下，侦听器将在组件渲染之前执行。设置 flush: &#39;post&#39; 将会使侦听器延迟到组件渲染之后再执行。详见回调的触发时机。在某些特殊情况下 (例如要使缓存失效)，可能有必要在响应式依赖发生改变时立即触发侦听器。这可以通过设置 flush: &#39;sync&#39; 来实现。然而，该设置应谨慎使用，因为如果有多个属性同时更新，这将导致一些性能和数据一致性的问题。</p><p>返回值是一个用来停止该副作用的函数。</p><p>示例 const count = ref(0)</p><p>watchEffect(() =&gt; console.log(count.value)) // -&gt; 输出 0</p><p>count.value++ // -&gt; 输出 1</p><p>副作用清除： watchEffect(async (onCleanup) =&gt; { const { response, cancel } = doAsyncWork(id.value) // <code>cancel</code> 会在 <code>id</code> 更改时调用 // 以便取消之前 // 未完成的请求 onCleanup(cancel) data.value = await response })</p><p>停止侦听器： const stop = watchEffect(() =&gt; {}) // 当不再需要此侦听器时: stop()</p><p>选项： watchEffect(() =&gt; {}, { flush: &#39;post&#39;, onTrack(e) { debugger }, onTrigger(e) { debugger } })</p><p>参考： watchPostEffect()​ watchEffect() 使用 flush: &#39;post&#39; 选项时的别名。</p><p>watchSyncEffect()​ watchEffect() 使用 flush: &#39;sync&#39; 选项时的别名。</p><p>watch()​ 侦听一个或多个响应式数据源，并在数据源变化时调用所给的回调函数。</p><p>类型 ts</p><p>为了便于阅读，对类型进行了简化。</p><p>详细信息 watch() 默认是懒侦听的，即仅在侦听源发生变化时才执行回调函数。</p><p>第一个参数是侦听器的源。这个来源可以是以下几种：</p><ul><li>一个函数，返回一个值</li><li>一个 ref</li><li>一个响应式对象</li><li>...或是由以上类型的值组成的数组</li></ul><p>第二个参数是在发生变化时要调用的回调函数。这个回调函数接受三个参数：新值、旧值，以及一个用于注册副作用清理的回调函数。该回调函数会在副作用下一次重新执行前调用，可以用来清除无效的副作用，例如等待中的异步请求。</p><p>当侦听多个来源时，回调函数接受两个数组，分别对应来源数组中的新值和旧值。</p><p>第三个可选的参数是一个对象，支持以下这些选项：</p><ul><li>immediate：在侦听器创建时立即触发回调。第一次调用时旧值是 undefined。</li><li>deep：如果源是对象，强制深度遍历，以便在深层级变更时触发回调。参考深层侦听器。</li><li>flush：调整回调函数的刷新时机。参考回调的刷新时机及 watchEffect()。</li><li>onTrack / onTrigger：调试侦听器的依赖。参考调试侦听器。</li></ul><p>与 watchEffect() 相比，watch() 使我们可以：</p><ul><li>懒执行副作用；</li><li>更加明确是应该由哪个状态触发侦听器重新执行；</li><li>可以访问所侦听状态的前一个值和当前值。</li></ul><p>示例 侦听一个 getter 函数： const state = reactive({ count: 0 })</p><p>watch( () =&gt; state.count, (count, prevCount) =&gt; { /* ... */ } )</p><p>侦听一个 ref： const count = ref(0) watch(count, (count, prevCount) =&gt; { /* ... */ })</p><p>当侦听多个来源时，回调函数接受两个数组，分别对应来源数组中的新值和旧值： watch([fooRef, barRef], ([foo, bar], [prevFoo, prevBar]) =&gt; { /* ... */ })</p><p>当使用 getter 函数作为源时，回调只在此函数的返回值变化时才会触发。如果你想让回调在深层级变更时也能触发，你需要使用 { deep: true } 强制侦听器进入深层级模式。在深层级模式时，如果回调函数由于深层级的变更而被触发，那么新值和旧值将是同一个对象。 const state = reactive({ count: 0 }) watch( () =&gt; state, (newValue, oldValue) =&gt; { // newValue === oldValue }, { deep: true } )</p><p>当直接侦听一个响应式对象时，侦听器会自动启用深层模式： const state = reactive({ count: 0 }) watch(state, () =&gt; { /* 深层级变更状态所触发的回调 */ }) watch() 和 watchEffect() 享有相同的刷新时机和调试选项：</p><p>watch(source, callback, { flush: &#39;post&#39;, onTrack(e) { debugger }, onTrigger(e) { debugger } })</p><p>停止侦听器： const stop = watch(source, callback) // 当已不再需要该侦听器时： stop()</p><p>副作用清理： watch(id, async (newId, oldId, onCleanup) =&gt; { const { response, cancel } = doAsyncWork(newId) // 当 <code>id</code> 变化时，<code>cancel</code> 将被调用， // 取消之前的未完成的请求 onCleanup(cancel) data.value = await response })</p><p>参考： 指南 - 侦听器 指南 - 侦听器调试</p></div>',1)])])}const h=e(n,[["render",l]]);export{d as __pageData,h as default};
